from collections import deque

def solve(n):
    initial_state = tuple(sorted([1] * n))
    queue = deque([(initial_state, 1)])
    visited = {initial_state}
    min_boxes = n

    while queue:
        state, dist = queue.popleft()
        min_boxes = min(min_boxes, len(state))
        if min_boxes == 1:
            break

        for i in range(len(state)):
            for j in range(i + 1, len(state)):
                m_i = state[i]
                m_j = state[j]
                for x in range(1, min(m_i, m_j) + 1):
                    new_state_list = []
                    for k in range(len(state)):
                        if k != i and k != j:
                            new_state_list.append(state[k])

                    if m_i - x > 0:
                        new_state_list.append(m_i - x)
                    if m_j - x > 0:
                        new_state_list.append(m_j - x)
                    new_state_list.append(2 * x)

                    new_state = tuple(sorted(new_state_list))
                    if new_state not in visited:
                        visited.add(new_state)
                        queue.append((new_state, dist + 1))
    return min_boxes

