    # we want to find min non-empty boxes
    # Use BFS to find min boxes
    initial_state = tuple(sorted([1] * n))
    queue = [(initial_state, 1)]
    visited = {initial_state}

    while queue:
        state, count = queue.pop(0)
        if len(state) == 1:
            return 1

        # Try all moves
        for i in range(len(state)):
            for j in range(i + 1, len(state)):
                m_i = state[i]
                m_j = state[j]
                for x in range(1, min(m_i, m_j) + 1):
                    new_state_list = []
                    for k in range(len(state)):
